<section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h3 mb-3">Minhas casas e solicitações</h2><?php if ($memberships): ?><div class="row g-3"><?php foreach ($memberships as $membership): ?><div class="col-12 col-md-6 col-xl-4"><article class="border rounded-4 p-3 h-100"><span class="badge <?php echo $membership['status'] === 'Ativo' ? 'text-bg-success' : ($membership['status'] === 'Recusado' ? 'text-bg-secondary' : 'text-bg-warning'); ?> mb-2"><?php echo e($membership['status']); ?></span><h3 class="h5"><?php echo e($membership['nome_exibicao']); ?></h3><p class="small mb-3">Papel: <strong><?php echo e(str_replace(['Assistencia','FilhoDeSanto','Babalorixa','Yalorixa'], ['Assistência','Filho de santo','Babalorixá','Yalorixá'], $membership['papel'])); ?></strong></p><?php if ($membership['status'] === 'Ativo' && $membership['tenant_status'] === 'Ativo'): ?><form method="post" action="select_tenant.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $membership['tenant_id']; ?>"><button class="btn btn-outline-primary w-100" type="submit">Acessar área da casa</button></form><?php else: ?><p class="small text-muted mb-0">Acompanhe por aqui. A decisão é comunicada pela casa ou pela administração global quando aplicável.</p><?php endif; ?></article></div><?php endforeach; ?></div><?php else: ?><p class="text-muted mb-0">Você ainda não possui vínculos. Use o diretório para conhecer uma casa e solicitar participação.</p><?php endif; ?></div></section>
